mapper.select:
SELECT mba.serial_number, process.`name` process_name, surplus.remark, team_user.user_name leader_name, cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.`name` 'monomer.name', pd.`name` 'area.name', mbf.`name` 'factory.name', mbw.`name` 'workshop.name', mbpl.`name` 'production_line.name', surplus.quantity FROM mes_building_produce_surplus surplus LEFT JOIN mes_building_process process ON surplus.process_id = process.id LEFT JOIN mes_building_team team ON surplus.team_id = team.id LEFT JOIN mes_building_team_user_link team_user ON surplus.team_id = team_user.team_id AND team_user.bool_delete_enum = FALSE AND team_user.bool_leader_enum = TRUE LEFT JOIN mes_building_task task ON task.id=surplus.task_id LEFT JOIN contract_project cp ON cp.id = task.project_id AND cp.bool_delete_enum = FALSE LEFT JOIN plan_monomer pm ON pm.id = task.monomer_id AND pm.bool_delete_enum = FALSE LEFT JOIN plan_area pd ON pd.id = task.area_id AND pd.bool_delete_enum = FALSE LEFT JOIN mes_building_factory mbf ON mbf.id = task.factory_id AND mbf.bool_delete_enum = FALSE LEFT JOIN mes_building_workshop mbw ON mbw.id = task.workshop_id AND mbw.bool_delete_enum = FALSE LEFT JOIN mes_building_production_line mbpl ON mbpl.id = task.production_line_id AND mbpl.bool_delete_enum =FALSE
LEFT JOIN tech_machine_part mba ON surplus.product_id =mba.id
LEFT JOIN tech_artifact mba ON surplus.product_id =mba.id
LEFT JOIN tech_enclosure mba ON surplus.product_id =mba.id
LEFT JOIN tech_assemble mba ON surplus.product_id =mba.id
surplus.bool_delete_enum=FALSE
AND task.project_id=#{projectId}
AND task.monomer_id=#{monomerId}
AND task.area_id=#{areaId}
AND task.factory_id=#{factoryId}
AND task.workshop_id=#{workshopId}
AND task.production_line_id=#{productionLineId}
AND team_user.user_name like =CONCAT('%',#{leaderName},'%')
AND process.`name` like CONCAT('%',#{processName},'%')
AND surplus.product_type =#{productType}
